		label.Font = FONT_MEDIUM
		label.TextSize = 12
		label.TextColor3 = theme.Text
		label.Size = UDim2.new(0, 0, 1, 0)
		label.AutomaticSize = Enum.AutomaticSize.X
		label.LayoutOrder = 2
		row = { frame = chip, img = img, label = label }
		headerchips.rows[i] = row
		return row
	end

